"use strict";(self.webpackChunkajaymore=self.webpackChunkajaymore||[]).push([["179"],{7821(e,t,o){o.r(t),o.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>m,frontMatter:()=>s,metadata:()=>i,toc:()=>h});var i=o(5230),a=o(4848),n=o(8453);let s={title:"Sing, Smile and do Service",date:new Date("2013-09-26T18:29:34.000Z"),authors:["ajay"],tags:["self development","embrace the new","service"],description:"What do we really want in life? The spiritualist, the philosopher, the psychologist, the school or college teacher, the affectionate father or a wise elder, all will give you their version of what it means to live. The problem is that none of these answers, however wise they seem really resolve the question. For that\u2026",image:"./smiley-faces-91.png",mdx:{format:"md"}},r,l={image:o(3628).A,authorsImageUrls:[void 0]},h=[];function u(e){let t={blockquote:"blockquote",br:"br",p:"p",strong:"strong",...(0,n.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.p,{children:"What do we really want in life? The spiritualist, the philosopher, the psychologist, the school or college teacher, the affectionate father or a wise elder, all will give you their version of what it means to live. The problem is that none of these answers, however wise they seem really resolve the question. For that question itself is life. Think about it; this profound question: what do I really want in life? Is all that is there to life? At times it seems like we do know the answer, but we keep coming back to the question, whatever be our age. It gives us a sense of purpose, a vision of destiny.\xa0"}),"\n","\n",(0,a.jsx)(t.p,{children:"Life is very dynamic, although we try and believe that everything is linked and there is an underlying order. Deep down we do know that work life can be surprising, painful at times. Many have tried simplifying this randomness of events in life through different ideas. For some it\u2019s a will of God, they believe this apparent chaos is actually order for the controlling & commanding god. For more intellectual types it might be the work of the subconscious mind or a result of collective consciousness of the societies etc. Whatever it is, it really doesn\u2019t matter life is chaotic."}),"\n",(0,a.jsx)(t.p,{children:"I am always fascinated by this dynamism of life events. The inherent uncertainty that surrounds us. Not knowing what might happen. Consider the daily traffic that we pass, countless small or big accidents have happened on that route. From my own driving experience I know for sure that our being a good driver or rider is not sufficient enough to insulate ourselves from a freak accident. The robbery next door in the same apartment, could have happened at our house also. There are so many evil things that happen to innocent people all the time; that sucks! But life works that way. Off course I should take into consideration the beautiful surprises too that happen along the way. A surprise visit by close friends. A sudden wonderful job opportunity that we never dreamed of, or a very rare lottery etc."}),"\n",(0,a.jsx)(t.p,{children:"However for untrained minds this randomness is too much. So some rely on religion and believe that their worship will in some way keep them safe and sound. Some Non-believers will confront this randomness of events with a nihilistic idea that there isn\u2019t much too the life any ways. The inquisitive will tackle it with their constant search to find meaning. For me any of this approach is just fine. But none of them make life fun at all. The wisdom that I share below is borrowed from core principals of an organization called Art Of Living. I happen to be an on-off volunteer associated with it. I really love their efforts at reducing all that unnecessary stress in the world. I summarize what I have learnt in three simple words: Sing, Smile & Service."}),"\n",(0,a.jsx)(t.p,{children:"Music is an integral part of our life and singing is a great stress buster. You don\u2019t need to be singer to sing. Just take some time to hum yourself a nice tune and see how it makes you a pound lighter, not literally \u{1F61B} . So sing by all the means. Some who really don\u2019t like singing, although I don\u2019t see why somebody will hate their own singing voice but still, you can pursue any art that may be more close to your taste. Take up some instrument, or start sketching, or start writing. In short just get yourself an interesting hobby that will make life really worth it. This sums up what I really mean by sing; have something in life that is close to your heart and you don\u2019t really expect any material gains from it."}),"\n",(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsxs)(t.p,{children:["Wear a smile and have friends; wear a scowl and have wrinkles.",(0,a.jsx)(t.br,{}),"\n",(0,a.jsx)(t.strong,{children:"George Eliot"})]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"That\u2019s exactly what it means. Smile is very integral to our well-being, and it truly makes you look younger. If you are not the smiley types just one suggestion to you as given by my teacher; \u201Cfake it, until you make it\u201D. A smile in your life will change you forever, it will make you more empathetic. Yes there are some people who appear all smiley and sugary on the outside but are completely rotten and corrupt, but that\u2019s not my point. You keep smiling starting now and see the world lighten up."}),"\n",(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsxs)(t.p,{children:["I slept and dreamt that life was joy. I awoke and saw that life was service. I acted and behold, service was joy.",(0,a.jsx)(t.br,{}),"\n",(0,a.jsx)(t.strong,{children:"Rabindranath Tagore"})]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Service is most ignored aspect of our life. People find gazillion reasons as to why they can\u2019t do service. For some service only means joining a NGO or some sort of volunteering. Service can be performed anywhere any time. Just be compassionate and have a simple thought. How can I make someone\u2019s day a little easier? From the time you wake up until you sleep, you will get more than a dozen opportunities to help someone. And dozen is just a smallish estimate, you will get many more opportunities if service is a habit for you. Well how does it help you? It\u2019s quite simple, service makes you lose yourself, and your consciousness expands. If I were a neuro-scientist I could tell you exactly what areas in your brain lighten up and which hormone get secreted, but you get the point. It makes you feel awesome. And don\u2019t forget to hold the smile."}),"\n",(0,a.jsx)(t.p,{children:"Just to summarize, remember to Sing, Smile & do Service. Be absolutely selfish about it. It has made my life much easier and might make yours too \u{1F642} . And all that life\u2019s randomness, trust me it won\u2019t bother you. You will show poise when in pain by smiling, you will relieve pain through your service and embrace the unknown through your singing."})]})}function m(e={}){let{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}},3628(e,t,o){o.d(t,{A:()=>i});let i=o.p+"assets/images/smiley-faces-91-1f14e8974256df8b7199aabd3faa6e76.png"},8453(e,t,o){o.d(t,{R:()=>s,x:()=>r});var i=o(6540);let a={},n=i.createContext(a);function s(e){let t=i.useContext(n);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),i.createElement(n.Provider,{value:t},e.children)}},5230(e){e.exports=JSON.parse('{"permalink":"/blog/2013/09/26/sing-smile-and-service","source":"@site/blog/2013-09-26-sing-smile-and-service/index.md","title":"Sing, Smile and do Service","description":"What do we really want in life? The spiritualist, the philosopher, the psychologist, the school or college teacher, the affectionate father or a wise elder, all will give you their version of what it means to live. The problem is that none of these answers, however wise they seem really resolve the question. For that\u2026","date":"2013-09-26T18:29:34.000Z","tags":[{"inline":true,"label":"self development","permalink":"/blog/tags/self-development"},{"inline":true,"label":"embrace the new","permalink":"/blog/tags/embrace-the-new"},{"inline":true,"label":"service","permalink":"/blog/tags/service"}],"readingTime":4.86,"hasTruncateMarker":true,"authors":[{"name":"Ajay More","title":"Maintainer of ajaymore.in","url":"https://github.com/ajaymore","imageURL":"https://avatars.githubusercontent.com/u/7659804?v=4","key":"ajay","page":null}],"frontMatter":{"title":"Sing, Smile and do Service","date":"2013-09-26T18:29:34.000Z","authors":["ajay"],"tags":["self development","embrace the new","service"],"description":"What do we really want in life? The spiritualist, the philosopher, the psychologist, the school or college teacher, the affectionate father or a wise elder, all will give you their version of what it means to live. The problem is that none of these answers, however wise they seem really resolve the question. For that\u2026","image":"./smiley-faces-91.png","mdx":{"format":"md"}},"unlisted":false,"prevItem":{"title":"Grit","permalink":"/blog/2013/10/03/grit"},"nextItem":{"title":"Movies to fuel your imagination","permalink":"/blog/2013/03/23/10-movies-to-fuel-your-imagination"}}')}}]);